SELECT inventory.product_id, inventory.store_id, store_sales.sale_date, store_sales.units, store_sales.store_id AS store_sale_store_id FROM inventory LEFT JOIN store_sales ON inventory.store_id = store_sales.store_id AND inventory.product_id = store_sales.product_id WHERE store_sales.sale_date >= '2023-08-20' ORDER BY store_sales.store_id DESC
